class Solution:
    def resultArray(self, nums, k, queries):
        n, self.k = len(nums), k
        size = 1
        while size < n:
            size *= 2
        self.size = size
        self.pr = [1] * (2 * size)
        self.ct = [[0] * k for _ in range(2 * size)]
        for i, v in enumerate(nums):
            self._set(i, v)
        res = []
        for idx, val, st, x in queries:
            self._set(idx, val)
            p, c = self._qry(st, n - 1, 1, 0, size - 1)
            res.append(c[x])
        return res

    def _set(self, i, v):
        i += self.size
        self.pr[i] = v % self.k
        self.ct[i] = [0] * self.k
        self.ct[i][self.pr[i]] = 1
        i >>= 1
        while i:
            self._pull(i)
            i >>= 1

    def _pull(self, i):
        lp, lc = self.pr[2 * i], self.ct[2 * i]
        rp, rc = self.pr[2 * i + 1], self.ct[2 * i + 1]
        c = rc[:]
        for s in range(self.k):
            if lc[s]:
                c[s * rp % self.k] += lc[s]
        self.pr[i] = lp * rp % self.k
        self.ct[i] = c

    def _qry(self, l, r, node, nl, nr):
        if r < nl or nr < l:
            idc = [0] * self.k
            idc[0] = 1
            return 1, idc
        if l <= nl and nr <= r:
            return self.pr[node], self.ct[node]
        mid = (nl + nr) // 2
        lp, lc = self._qry(l, r, 2 * node, nl, mid)
        rp, rc = self._qry(l, r, 2 * node + 1, mid + 1, nr)
        c = rc[:]
        for s in range(self.k):
            if lc[s]:
                c[s * rp % self.k] += lc[s]
        return lp * rp % self.k, c

