class Solution {
    int K, sz;
    vector<int> pr;
    vector<array<int,5>> ct;

    void pull(int i) {
        int lp = pr[2*i], rp = pr[2*i+1];
        auto c = ct[2*i+1];
        for (int s = 0; s < K; s++)
            if (ct[2*i][s]) c[s*rp%K] += ct[2*i][s];
        pr[i] = (int)((long long)lp * rp % K);
        ct[i] = c;
    }
    void setLeaf(int i, int v) {
        i += sz;
        pr[i] = v % K;
        ct[i] = {};
        ct[i][pr[i]] = 1;
        for (i >>= 1; i >= 1; i >>= 1) pull(i);
    }
    int ql, qr;
    pair<int,array<int,5>> qry(int node, int nl, int nr) {
        array<int,5> id{}; id[0] = 1;
        if (qr < nl || nr < ql) return {1, id};
        if (ql <= nl && nr <= qr) return {pr[node], ct[node]};
        int mid = (nl + nr) / 2;
        auto L = qry(2*node, nl, mid), R = qry(2*node+1, mid+1, nr);
        auto c = R.second;
        for (int s = 0; s < K; s++)
            if (L.second[s]) c[s*R.first%K] += L.second[s];
        return {(int)((long long)L.first * R.first % K), c};
    }
public:
    vector<int> resultArray(vector<int>& nums, int k, vector<vector<int>>& queries) {
        int n = nums.size(); K = k;
        sz = 1; while (sz < n) sz *= 2;
        pr.assign(2*sz, 1);
        ct.assign(2*sz, {});
        for (int i = 0; i < n; i++) setLeaf(i, nums[i]);
        vector<int> res;
        for (auto& q : queries) {
            setLeaf(q[0], q[1]);
            ql = q[2]; qr = n - 1;
            auto ans = qry(1, 0, sz - 1).second;
            res.push_back(ans[q[3]]);
        }
        return res;
    }
};

