var resultArray = function(nums, k, queries) {
    const n = nums.length, K = k;
    let sz = 1;
    while (sz < n) sz *= 2;
    const pr = new Array(2 * sz).fill(1);
    const ct = Array.from({length: 2 * sz}, () => new Array(K).fill(0));
    const pull = i => {
        const lp = pr[2*i], rp = pr[2*i+1];
        const c = ct[2*i+1].slice();
        for (let s = 0; s < K; s++)
            if (ct[2*i][s]) c[s*rp%K] += ct[2*i][s];
        pr[i] = lp * rp % K;
        ct[i] = c;
    };
    const setLeaf = (i, v) => {
        i += sz;
        pr[i] = v % K;
        ct[i] = new Array(K).fill(0);
        ct[i][pr[i]] = 1;
        for (i >>= 1; i >= 1; i >>= 1) pull(i);
    };
    let ql, qr;
    const qry = (node, nl, nr) => {
        const id = new Array(K).fill(0); id[0] = 1;
        if (qr < nl || nr < ql) return [1, id];
        if (ql <= nl && nr <= qr) return [pr[node], ct[node]];
        const mid = (nl + nr) >> 1;
        const [lp, lc] = qry(2*node, nl, mid);
        const [rp, rc] = qry(2*node+1, mid+1, nr);
        const c = rc.slice();
        for (let s = 0; s < K; s++)
            if (lc[s]) c[s*rp%K] += lc[s];
        return [lp * rp % K, c];
    };
    for (let i = 0; i < n; i++) setLeaf(i, nums[i]);
    const res = [];
    for (const [idx, val, st, x] of queries) {
        setLeaf(idx, val);
        ql = st; qr = n - 1;
        res.push(qry(1, 0, sz - 1)[1][x]);
    }
    return res;
};
